using LiveCG.Core;
using SkiaSharp;
internal static class V123Checks
{
    public static async Task Run(string folder,Action<bool,string> check)
    {
        var synthetic=LiveCG.Testing.TestFixtures.NumericRedraw(Path.Combine(folder,"v123-synthetic"));Repro(folder,check,synthetic);var local=Environment.GetEnvironmentVariable("LIVECG_TEST_PRICE_IMAGE");if(File.Exists(local))Repro(folder,check);
        using var full=SourceImage.Read(synthetic)!;var region=new EffectRegion{Bounds=new(659d/full.Width,718d/full.Height,193d/full.Width,52d/full.Height),Role=RegionRole.Group,ContentOnly=true,SeparationTarget=SeparationTarget.Text,TextSettings=new(){RangeMode=true},Clips=[new(){Duration=1,Options=new(){Kind=EffectKind.DigitRoll}}]};using var scene=new EffectScene(full);var cells=scene.DigitBounds(region);var slots=DigitRollLayout.Create(cells,193);check(slots.Count==6&&slots.Zip(cells).All(p=>p.First.Window.Left<=p.Second.MidX&&p.First.Window.Right>=p.Second.MidX),"rolling windows contain every original digit center without changing glyph bounds");check(slots.Zip(slots.Skip(1)).All(p=>p.First.Window.Right==p.Second.Window.Left),"automatic rolling viewports meet at shared boundaries without overlap");
        var manual=DigitRollLayout.Create(cells,193,[.16,.32,.53,.69,.84]);check(manual[0].Window.Right==(float)(193*.16)&&manual[1].Window.Left==manual[0].Window.Right,"manual numeric dividers remain authoritative for rolling viewports");
        for(var digit=0;digit<10;digit++)
        {
            region.Clips[0].Id=new Guid(digit,0,0,new byte[8]);using var rendered=scene.Render([region],new(),0);using var crop=new SKBitmap();rendered.ExtractSubset(crop,ObjectExtractor.PixelRect(region.Bounds,full.Width,full.Height));using var reference=new SKBitmap(crop.Width,crop.Height);reference.Erase(SKColors.Transparent);using(var c=new SKCanvas(reference))using(var font=new SKFont(SKTypeface.FromFamilyName("Arial",SKFontStyle.Bold),slots[0].FontSizes[digit]))using(var p=new SKPaint{Color=SKColors.White,IsAntialias=true}){font.MeasureText(digit.ToString(),out var b);c.DrawText(digit.ToString(),cells[0].MidX-b.MidX,cells[0].MidY-b.MidY,font,p);}var needed=0;var missing=0;for(var y=0;y<reference.Height;y++)for(var x=0;x<Math.Min(reference.Width,cells[1].Left);x++){if(reference.GetPixel(x,y).Alpha<230)continue;needed++;var c=crop.GetPixel(x,y);if(c.Red<200||c.Green<200||c.Blue<200)missing++;}check(needed>0&&missing<=Math.Max(2,needed*.02),"new effect seed "+digit+" shows the complete rolling digit in an original narrow 1 slot");
        }
        using(var final=scene.Render([region],new(),1))check(final.Bytes.SequenceEqual(full.Bytes),"rolling completion restores the original price pixels and stroke thickness exactly");
        await Fixture(synthetic,"redraw-price.obs",false);await Fixture(synthetic,"redraw-manual.obs",true);if(File.Exists(local))await Fixture(local!,"local-redraw.obs",false);
        async Task Fixture(string imagePath,string name,bool manualCells)
        {
            using var original=SourceImage.Read(imagePath)!;using var context=new SKBitmap();original.ExtractSubset(context,new(630,700,985,785));var sourcePath=Path.Combine(folder,"v123-synthetic",name+".png");SourceImage.SavePng(context,sourcePath);
            var price=new EffectRegion{Bounds=new(29d/355,18d/85,193d/355,52d/85),Role=RegionRole.Group,ContentOnly=true,SeparationTarget=SeparationTarget.Text,TextSettings=new(){RangeMode=true},Clips=[new(){Id=Guid.Empty,Duration=1,Options=new(){Kind=EffectKind.DigitRoll}}]};if(manualCells)price.DigitDividers=[.16,.32,.53,.69,.84];var discount=new EffectRegion{Bounds=new(277d/355,27d/85,40d/355,32d/85),ContentOnly=true,SeparationTarget=SeparationTarget.Text,TextSettings=new(){RangeMode=true},Clips=[new(){Id=new Guid(3,0,0,new byte[8]),Duration=1,Options=new(){Kind=EffectKind.DigitRoll}}]};var job=new ImageJob{SourcePath=sourcePath,Width=355,Height=85,Regions=[price,discount]};var destination=Path.Combine(folder,name);await new BrowserExporter().ExportAsync(job,new(){Fps=30,EndHold=0},destination,true,null,CancellationToken.None);Directory.CreateDirectory(Path.Combine(destination,"expected"));using var frames=new EffectScene(context);foreach(var time in new[]{0,.2,.6,1d}){using var frame=frames.Render(job.Regions,new(),time);SourceImage.SavePng(frame,Path.Combine(destination,"expected",time.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture)+".png"));check(frame.GetPixel(244,42)==context.GetPixel(244,42),name+" leaves the original won suffix unchanged at "+time);if(manualCells&&time==0){var mismatches=0;for(var y=50;y<68;y++)for(var x=122;x<132;x++){var a=context.GetPixel(x,y);var b=frame.GetPixel(x,y);if((a.Red>230&&a.Green>230&&a.Blue>230)!=(b.Red>230&&b.Green>230&&b.Blue>230))mismatches++;}check(mismatches<=2,"manual numeric cells retain the comma as a fixed original symbol");}}check(File.ReadAllText(Path.Combine(destination,"data.js")).Contains("rollSlots")&&File.ReadAllText(Path.Combine(destination,"data.js")).Contains("rollGlyphs"),name+" exports native rolling window and fitted-size metadata");
        }
    }
    public static void Repro(string folder,Action<bool,string> check,string? sourcePath=null)
    {
        var path=sourcePath??Environment.GetEnvironmentVariable("LIVECG_TEST_PRICE_IMAGE");if(!File.Exists(path))throw new FileNotFoundException("Set LIVECG_TEST_PRICE_IMAGE for the local source-image check.");using var source=SourceImage.Read(path)!;var dir=Path.Combine(folder,sourcePath is null?"v123-local":"v123-synthetic");Directory.CreateDirectory(dir);using var warm=new EffectScene(source);
        foreach(var range in new[]{false,true})foreach(var delta in new[]{0,-2,-1,1,2})
        {
            var bounds=new NormalizedRect((659d+delta)/source.Width,(718d+delta)/source.Height,193d/source.Width,52d/source.Height);var region=new EffectRegion{Bounds=bounds,Role=RegionRole.Group,ContentOnly=true,SeparationTarget=SeparationTarget.Text,TextSettings=new(){RangeMode=range},Clips=[new(){Duration=1,Options=new(){Kind=EffectKind.DigitRoll}}]};
            using var crop=ObjectExtractor.CropObject(source,region);using var measurement=new EffectScene(source);var auto=measurement.DigitBounds(region);var background=DigitCells.DetectionBackground(crop,RegionSeparation.Background(source,region));Console.WriteLine($"PRICE range={range} delta={delta} bg={background} cells={auto.Count}: "+string.Join(";",auto.Select(r=>$"{r.Left:0.0},{r.Top:0.0},{r.Width:0.0},{r.Height:0.0}")));check(auto.Count==6,"provided textured price automatic cells range="+range+" delta="+delta);
            var known=DigitCells.Find(crop,RegionSeparation.Background(source,region));Console.WriteLine("REFERENCE-BACKGROUND heights="+string.Join(',',known.Select(c=>c.Height)));if(range&&delta==0)check(auto.All(c=>Math.Abs(c.Height-42)<=3),"textured background remnants cannot inflate the last rolling price digit height");
            using var a=warm.Render([region],new(),.2);using var cold=new EffectScene(source);using var b=cold.Render([region],new(),.2);check(a.Bytes.SequenceEqual(b.Bytes),"warm/cold numeric rendering equality range="+range+" delta="+delta);SourceImage.SavePng(crop,Path.Combine(dir,$"price-{range}-{delta}.png"));
        }
        var discount=new EffectRegion{Bounds=new(907d/source.Width,727d/source.Height,40d/source.Width,32d/source.Height),ContentOnly=true,SeparationTarget=SeparationTarget.Text,TextSettings=new(){RangeMode=true}};using var digits=ObjectExtractor.CropObject(source,discount);var found=DigitCells.Find(digits,DigitCells.Background(digits,SKColors.Transparent));Console.WriteLine("DISCOUNT numeric cells="+found.Count);check(found.Count==2,"provided discount detects its two digits separately from percent symbol");SourceImage.SavePng(digits,Path.Combine(dir,"discount.png"));
        var first=new EffectRegion{Bounds=new(659d/source.Width,718d/source.Height,193d/source.Width,52d/source.Height),ContentOnly=true,Role=RegionRole.Group,SeparationTarget=SeparationTarget.Text,Clips=[new(){Id=Guid.Empty,Duration=1,Options=new(){Kind=EffectKind.DigitRoll}}]};using var original=ObjectExtractor.CropObject(source,first);using var scene=new EffectScene(source);var cells=scene.DigitBounds(first);var firstLayout=DigitRollLayout.Create(cells,original.Width);using var rendered=scene.Render([first],new(),0);using var price=new SKBitmap();rendered.ExtractSubset(price,ObjectExtractor.PixelRect(first.Bounds,source.Width,source.Height));SourceImage.SavePng(price,Path.Combine(dir,"rolling-price-zero.png"));
        using var reference=new SKBitmap(original.Width,original.Height);reference.Erase(SKColors.Transparent);using(var c=new SKCanvas(reference))using(var font=new SKFont(SKTypeface.FromFamilyName("Arial",SKFontStyle.Bold),firstLayout[0].FontSizes[0]))using(var paint=new SKPaint{Color=SKColors.White,IsAntialias=true}){font.MeasureText("0",out var bounds);c.DrawText("0",cells[0].MidX-bounds.MidX,cells[0].MidY-bounds.MidY,font,paint);}var want=0;var missing=0;for(var y=0;y<reference.Height;y++)for(var x=0;x<Math.Min(reference.Width,cells[1].Left);x++){var r=reference.GetPixel(x,y);if(r.Alpha<230)continue;want++;var actual=price.GetPixel(x,y);if(actual.Red<200||actual.Green<200||actual.Blue<200)missing++;}Console.WriteLine($"NARROW FIRST DIGIT: {missing}/{want} visible zero-glyph pixels missing after a new effect seed");check(want>100&&missing<want*.02,"provided narrow original digit 1 can roll a complete wider digit 0 without horizontal chopping");SourceImage.SavePng(reference,Path.Combine(dir,"first-reference.png"));
        using var wide=new SKBitmap();source.ExtractSubset(wide,new SKRectI(630,700,905,785));SourceImage.SavePng(wide,Path.Combine(dir,"source-wide.png"));
    }
}
